#include "Rover.h"

void setup() {
  int up = distanceAhead();
  turnRight();
  turnRight();
  int down = distanceAhead();
  int rows = (down - up) / 2;
  if (rows > 0) {
    forward(rows);
  }
  if (rows < 0) {
    backward(-rows);
  }

  turnRight();
  int left = distanceAhead();
  turnRight();
  turnRight();
  int right = distanceAhead();
  int cols = (right - left) / 2;
  if (cols > 0) {
    forward(cols);
  }
  if (cols < 0) {
    backward(-cols);
  }
}

void loop() {
}
